window.__saqPaperQuestions("2025-2-liverpool",[{"number":1,"title":"","stemText":"62yo man brought in by ambulance with out of hospital cardiac arrest with ongoing Cardiopulmonary resuscitation (CPR) in progress.","parts":[{"id":"a","label":"Part A","prompt":"In the table below, list four (4) reversible causes with sonographic features that can be identified using POCUS (Point Of Care Ultrasound) in the Emergency Department. 8 marks Reversible cause Ultrasound finding"},{"id":"b","label":"Part B","prompt":"What is Pseudo-PEA and its implication in the management of cardiac arrest patients.1mark"},{"id":"c","label":"Part C","prompt":"Name Two (2) clinical trials supporting POCUS in cardiac arrest.1 mark"},{"id":"d","label":"Part D","prompt":"List Four (4) indications for Cessation of CPR. 4 marks"},{"id":"e","label":"Part E","prompt":"List 4 indications for prolonged CPR in cardiac arrest. 4 marks"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Cause</th><th>Distinguishing feature</th></tr></thead><tbody><tr><td>Ultrasound finding</td><td></td></tr><tr><td>Cardiac tamponade</td><td>Large/massive pericardial effusion</td></tr><tr><td>Massive Pulmonary Embolism</td><td>Large, dilated RV, D shaped septum</td></tr><tr><td>Haemorrhagic shock</td><td>Abdominal free fluid</td></tr><tr><td>Tension Pneumothorax</td><td>Absent lung sliding</td></tr><tr><td>Above knee DVT /Thrombosis</td><td>Non compressible deep veins/femoral</td></tr><tr><td>Abdominal Aortic aneurysm rupture</td><td>Large Abdominal aorta</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Pseudo-PEA can be defined as evidence of cardiac activity without a detectable pulse  (severe</div><div class=\"answer-line\">shock state). Distinguishing pseudo-PEA from true PEA is important for emergency physicians</div><div class=\"answer-line\">as the prognosis and management of these patients differ.</div><div class=\"answer-line\">Pseudo-PEA- may see very low BP with arterial line, POCUS may show organised cardiac</div><div class=\"answer-line\">activity, may have high end tidal CO2</div><div class=\"answer-line\">Identifying patients in pseudo-PEA can help guide resuscitation decisions, improve</div><div class=\"answer-line\">outcome/prognosis in cardiac arrest</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">“The Focused Echocardiographic Evaluation in Life support (FEEL) study showed that 38% of</div><div class=\"answer-line\">patients with asystole on ECG, and 58% of patients in PEA, had coordinated cardiac motion</div><div class=\"answer-line\">associated with increased survival.”</div><div class=\"answer-line\">The REASON trial found that 54% of patients with suspected PEA and 10% of suspected</div><div class=\"answer-line\">asystole patients had mechanical activity (Gaspari 2016)</div><div class=\"answer-line\"><strong>d-List Four (4) indications for Cessation of CPR (Cardio Pulmonary Resuscitation) – 4marks </strong></div><div class=\"answer-line\"><strong>In event of ROSC </strong></div><div class=\"answer-line\">•only once you are sure that adequate perfusion is present</div><div class=\"answer-line\">Liverpool FEx 2025.2                                                                                                            P Nanaware/J Davidson</div><div class=\"answer-line\">-patient is moving</div><div class=\"answer-line\">-ETCO2 is rising</div><div class=\"answer-line\">-there is a stable cardiac rhythm of suitable rate</div><div class=\"answer-line\"><strong>if No ROSC </strong></div><div class=\"answer-line\"><strong>•20 minutes of CPR without reversible cause and all of the following </strong></div><div class=\"answer-line\">-non shockable rhythm and</div><div class=\"answer-line\">-no ROSC before ED arrival or age &gt; 80 years</div><div class=\"answer-line\">-non witnessed arrest</div><div class=\"answer-line\"><strong>•trauma and absent cardiac activity on bedside echocardiography </strong></div><div class=\"answer-line\">-99% mortality if cardiac activity absent</div><div class=\"answer-line\">-70% mortality if cardiac activity present</div><div class=\"answer-line\"><strong>•absent cardiac activity on US and ETCO2 &lt; 10mmHg after second cycle of ALS </strong></div><div class=\"answer-line\">-estimated to be 0% survival</div><div class=\"answer-line\">•in PEA/asystole - presence of</div><div class=\"answer-line\">-OHCA not witnessed by emergency medical services personnel</div><div class=\"answer-line\">-no ROSC before 3rd dose of 1mg of adrenaline</div><div class=\"answer-line\">-survival to hospital discharge 0% (95% CI 0 - 0.5%)</div><div class=\"answer-line\">•lactate &gt; 18mmol/L</div><div class=\"answer-line\">•venous pO2 &lt; 7mmHg</div><div class=\"answer-line\"><strong>e-List 4 indications for prolonged CPR (Cardio Pulmonary Resuscitation) in cardiac arrest 4 </strong></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">-poisoning</div><div class=\"answer-line\">-severe hypothermia &lt;34 degrees</div><div class=\"answer-line\">-Pulmonary Embolism if thrombolytic administered</div><div class=\"answer-line\">-pregnancy if resuscitative hysterotomy performed</div><div class=\"answer-line\">-Bridge to ECMO for urgent coronary reperfusion in cath lab</div><div class=\"answer-line\">- drowning</div><div class=\"answer-line\">-asthma- needs qualifier eg PTx, bridge to ECMO</div><div class=\"answer-line\">Liverpool FEx 2025.2                                                                                                            P Nanaware/J Davidson</div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\">Cessation of CPR • LITFL</div><div class=\"answer-line\">Managing Cardiac Arrest Using Ultrasound - Annals of Emergency Medicine</div><div class=\"answer-line\">PEA Arrest, PseudoPEA &amp; PREM | Emergency Medicine Cases</div><div class=\"answer-line\">Pulseless Electrical Activity • LITFL • CCC Resuscitation</div><div class=\"answer-line\">Pseudo-pulseless electrical activity in the emergency department, an evidence based approach</div><div class=\"answer-line\">- ScienceDirect</div><div class=\"answer-line\">Liverpool FEx 2025.2                                                                                                            P Nanaware/J Davidson</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":2,"title":"","stemText":"A 13-year-old girl presents to ED with 2 days of cough and progressive dyspnoea.\nOn arrival she is in severe respiratory distress and bilateral wheeze is auscultated throughout all lung fields.","parts":[{"id":"a","label":"Part A","prompt":"List Four (4) features on history that increases her risk of a poor outcome. 4 marks"},{"id":"b","label":"Part B","prompt":"Complete the table below regarding of features according to severity of asthma. 6 marks"},{"id":"c","label":"Part C","prompt":"Nebulisers are sometimes used instead of puffers (metered dose inhalers) in the acute setting. List below 2 advantages and 2 disadvantages of nebulisers compared to puffers4 marks Advantages Disadvantage"},{"id":"d","label":"Part D","prompt":"List Four (4) side effects of beta-2 agonists, each from a different system (4 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><em>NICE guidelines</em>:</div><div class=\"answer-line\">a. Noncompliance to medications</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\"><em>NICE guidelines</em>:</td></tr><tr><td colspan=\"2\">a. Noncompliance to medications</td></tr><tr><td colspan=\"2\">b. Over-use of short acting beta 2 agonist medications</td></tr><tr><td colspan=\"2\">c. Needing 2 or more courses of oral steroids per year</td></tr><tr><td colspan=\"2\">d. 2 or more visits to an emergency department in the past year, or any hospital</td></tr><tr><td colspan=\"2\">admission</td></tr><tr><td colspan=\"2\">e. Any previous ICU admission</td></tr><tr><td colspan=\"2\"><em>May also consider giving marks for the following: </em></td></tr><tr><td>•</td><td>Poor inhaler technique</td></tr><tr><td>•</td><td>Night time symptoms (&gt;1/week)</td></tr><tr><td>•</td><td>Poor perception of symptoms</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Option</th><th>Advantage</th><th>Disadvantage</th></tr></thead><tbody><tr><td><strong>b-Complete the table below regarding classification of severity of respiratory distress (6 </strong></td><td><strong>marks, ½ mark per answer)  </strong></td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">admission</td></tr><tr><td colspan=\"2\">e. Any previous ICU admission</td></tr><tr><td colspan=\"2\"><em>May also consider giving marks for the following: </em></td></tr><tr><td>•</td><td>Poor inhaler technique</td></tr><tr><td>•</td><td>Night time symptoms (&gt;1/week)</td></tr><tr><td>•</td><td>Poor perception of symptoms</td></tr><tr><td colspan=\"2\"><strong>b-Complete the table below regarding classification of severity of respiratory distress (6 </strong></td></tr><tr><td colspan=\"2\"><strong>marks, ½ mark per answer)  </strong></td></tr><tr><td colspan=\"2\">Nebulisers are sometimes used instead of puffers (metered dose inhalers) in the acute setting<strong>.  </strong></td></tr><tr><td colspan=\"2\"><strong>c-List below (2) advantages and (2) disadvantages of nebulisers compared to puffers (4 </strong></td></tr><tr><td colspan=\"2\"><strong>marks): </strong></td></tr><tr><td colspan=\"2\">f. Advantages:</td></tr><tr><td colspan=\"2\">i. Does not require patient coordination, good for young children, elderly</td></tr><tr><td colspan=\"2\">ii. More effective when patient has markedly reduced tidal volumes</td></tr><tr><td colspan=\"2\">iii. Less training in use</td></tr><tr><td colspan=\"2\">g. Disadvantages:</td></tr><tr><td colspan=\"2\">i. Reduced dose of drug reaches small airways – less effect</td></tr><tr><td colspan=\"2\">ii. Larger dose of drug swallowed – increased side effects</td></tr><tr><td colspan=\"2\">Liverpool FEx 2025.2                                                                                                            P Nanaware/J Davidson</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":3,"title":"","stemText":"40y/o woman presented to Emergency Department with sudden onset diplopia. She is otherwise fit and healthy. She does not take any regular medications","parts":[{"id":"a","label":"Part A","prompt":"State how would you assess if it is Monocular or Binocular diplopia. 2 marks"},{"id":"b","label":"Part B","prompt":"In the table below list Four (4) causes for Monocular Diplopia. 4 marks Causes"},{"id":"c","label":"Part C","prompt":"In the table below List Six (6) causes of binocular diplopia and corresponding examination or history finding for each cause. 6marks Causes History or examination finding"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><strong>Monocular diplopia</strong>: usually persists when the unaffected eye is closed or covered.</div><div class=\"answer-line\">In other words, the patient still experiences diplopia when viewing with only the affected eye.</div><div class=\"answer-line\"><strong>Binocular diplopia: </strong> resolves with either eye being closed or covered, indicating ocular</div><div class=\"answer-line\">misalignment as an underlying problem</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Corneal pathologies:</td></tr><tr><td>•</td><td>Refractive error</td></tr><tr><td>•</td><td>Keratoconus</td></tr><tr><td>•</td><td>Dry eye syndrome</td></tr><tr><td>•</td><td>Corneal scarring</td></tr><tr><td colspan=\"2\">Cataract</td></tr><tr><td colspan=\"2\">Maculopathy (macular</td></tr><tr><td colspan=\"2\">degeneration)</td></tr><tr><td colspan=\"2\">Post ocular surgery</td></tr><tr><td colspan=\"2\">Liverpool FEx 2025.2                                                                                                            P Nanaware/J Davidson</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Cause</th><th>Distinguishing feature</th></tr></thead><tbody><tr><td>Corneal pathologies:</td><td></td></tr><tr><td>•</td><td>Refractive error</td></tr><tr><td>•</td><td>Keratoconus</td></tr><tr><td>•</td><td>Dry eye syndrome</td></tr><tr><td>•</td><td>Corneal scarring</td></tr><tr><td>Cataract</td><td></td></tr><tr><td>Maculopathy (macular</td><td></td></tr><tr><td>degeneration)</td><td></td></tr><tr><td>Post ocular surgery</td><td></td></tr><tr><td>Liverpool FEx 2025.2                                                                                                            P Nanaware/J Davidson</td><td></td></tr><tr><td><strong>examination or history finding for each causes 6marks </strong></td><td></td></tr><tr><td>Liverpool FEx 2025.2                                                                                                            P Nanaware/J Davidson</td><td></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":4,"title":"","stemText":"78-year-old gentleman presents with a fall and a painful left hip. His Xray is below","parts":[{"id":"a","label":"Part A","prompt":"List Four (4) contraindications for procedural sedation to reduce a dislocated hip in the ED. 4 marks"},{"id":"b","label":"Part B","prompt":"Name and describe a technique for Hip Reduction. 4marks"},{"id":"c","label":"Part C","prompt":"List your Four (4) management priorities post reduction. 4marks"}],"propPages":["asset:img450010c212eeabf37f"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Previous recurrent dislocation requiring reduction in OT</div><div class=\"answer-line\">Non fasting status</div><div class=\"answer-line\">Known or anticipated difficult airway</div><div class=\"answer-line\">Significant medical co morbidities, ASA III-IV</div><div class=\"answer-line\">Untrained staff</div><div class=\"answer-line\">Overwhelmed unsafe department</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Patient supine</div><div class=\"answer-line\">Firm distal traction at flexed knee(to pull head back into the acetabulum)</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Liverpool FEx 2025.2                                                                                                            P Nanaware/J Davidson</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":5,"title":"","stemText":"A 35 year old emerged from a beach in Northern Australia 10 minutes ago and has developed\nvomiting, diaphoresis and severe back and abdominal pain. There are no visible welts or dermal markings.","parts":[{"id":"a","label":"Part A","prompt":"List Four (4) symptoms of Irukandji envenomation. 4 marks"},{"id":"b","label":"Part B","prompt":"The patient is transferred via ambulance to your Emergency Department. List your Six (6) management priorities.6 marks"},{"id":"c","label":"Part C","prompt":"State two (2) differences in the clinical presentation of envenomation from box jellyfish compared to Irukandji syndrome. 2 marks"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Dysphoria</td></tr><tr><td>-</td><td>Agitation</td></tr><tr><td>-</td><td>Vomiting</td></tr><tr><td>-</td><td>Diaphoresis</td></tr><tr><td>-</td><td>Back, limb and abdominal pain</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>-</td><td>Dysphoria</td></tr><tr><td>-</td><td>Agitation</td></tr><tr><td>-</td><td>Vomiting</td></tr><tr><td>-</td><td>Diaphoresis</td></tr><tr><td>-</td><td>Back, limb and abdominal pain</td></tr><tr><td>-</td><td>Hypertension</td></tr><tr><td>-</td><td>Tachycardia</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Liverpool FEx 2025.2                                                                                                            P Nanaware/J Davidson</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":6,"title":"","stemText":"You are the medical director of a regional emergency department planning to establish an emergency department short staff unit (EDSSU).","parts":[{"id":"a","label":"Part A","prompt":"As part of your guidelines for the model of care for the EDSSU,List six (6) exclusion criteria for\nadmission to EDSSU. 6 marks"},{"id":"b","label":"Part B","prompt":"List three (3) functional requirements of the physical space for the EDSSU. 3 marks"},{"id":"c","label":"Part C","prompt":"List three (3) key performance indicators that will be monitored to ensure the EDSSU functions in accordance with its model of care. 3 marks"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">-Anticipated duration of treatment is more than 24 hours.</div><div class=\"answer-line\">-The patient is admitted under the care of an inpatient team.</div><div class=\"answer-line\">-The patient has been transferred to the hospital for admission under care of an inpatient team.</div><div class=\"answer-line\">-The patient is clinically unstable.</div><div class=\"answer-line\">-The patient has complex care needs which are unable to be met in the ED SSU.</div><div class=\"answer-line\">-The patient remains undifferentiated and has an unclear management plan.</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">-Anticipated duration of treatment is more than 24 hours.</div><div class=\"answer-line\">-The patient is admitted under the care of an inpatient team.</div><div class=\"answer-line\">-The patient has been transferred to the hospital for admission under care of an inpatient team.</div><div class=\"answer-line\">-The patient is clinically unstable.</div><div class=\"answer-line\">-The patient has complex care needs which are unable to be met in the ED SSU.</div><div class=\"answer-line\">-The patient remains undifferentiated and has an unclear management plan.</div><div class=\"answer-line\">-requires advanced physiological monitoring</div><div class=\"answer-line\">-requires increased supervision, for example behavioural disturbance; and/or</div><div class=\"answer-line\">-Requires assistance in transfers beyond the staffing capacity</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Liverpool FEx 2025.2                                                                                                            P Nanaware/J Davidson</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":7,"title":"","stemText":"A 6-year-old girl is brought in by her mother with abdominal pain and a history of not passing\nurine for more than 12 hours.\nYou suspect she has urinary retention.","parts":[{"id":"a","label":"Part A","prompt":"List four (4) possible causes of this.4 marks"},{"id":"b","label":"Part B","prompt":"List and justify three (3) investigations you would order in ED. 3 marks"},{"id":"c","label":"Part C","prompt":"Bedside ultrasound shows a large bladder. Outline the steps to address her urinary retention in the ED.5 marks"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Mechanical obstruction-pelvic mass, labial adhesions</div><div class=\"answer-line\">•</div><div class=\"answer-line\"><strong>Infection-</strong> UTI, pyelonephritis</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Constipation</div><div class=\"answer-line\">•</div><div class=\"answer-line\">Medication- anticholinergics- antihistamines eg. promethazine, alpha agonists,</div><div class=\"answer-line\">•</div><div class=\"answer-line\">Voiding dysfunction/ behavioural</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Malignancy- dermoid cyst, sacrococcygeal teratoma, neuroblastoma, pelvic</div><div class=\"answer-line\">mass</div><div class=\"answer-line\">•</div><div class=\"answer-line\">Kidney stone</div><div class=\"answer-line\">Liverpool FEx 2025.2                                                                                                            P Nanaware/J Davidson</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":8,"title":"","stemText":"A 57 yo man with known alcohol-related cirrhosis presents with abdominal pain and a fever. On examination he has gross ascites and a diffusely tender abdomen. You decide to perform an ascitic tap.","parts":[{"id":"a","label":"Part A","prompt":"List Three (3) potential complications of an ascitic tap. For each complication state how you would mitigate the risk of this occurring.6 marks Complication Mitigation strategy"},{"id":"b","label":"Part B","prompt":"List Three (3) criteria in the ascitic fluid that would favour a diagnosis of secondary rather than primary bacterial peritonitis. 3 marks. The ascitic fluid demonstrates a neutrophil count of >250/ml but none of the other features listed above."},{"id":"c","label":"Part C","prompt":"List two (2) common microorganisms likely to cause this. 2 marks"},{"id":"d","label":"Part D","prompt":"What is the typical biochemical finding associated with ascites related to portal hypertension? 1 mark"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Risk / issue</th><th>Mitigation / management</th></tr></thead><tbody><tr><td>A 57 yo man with known alcohol-related cirrhosis presents with abdominal pain and a fever. On</td><td>examination he has gross ascites and a diffusely tender abdomen. You decide to perform an</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><strong>a-List Three (3) potential complications of an ascitic tap. For each complication state how </strong></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Bowel injury</div><div class=\"answer-line\">Use ultrasound to confirm appropriate pocket of fluid.</div><div class=\"answer-line\">Avoid areas with surgical scarring</div><div class=\"answer-line\">Bleeding</div><div class=\"answer-line\">Ensure INR&lt; 2 and platelets &gt;50</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Infection</div><div class=\"answer-line\">Strict aseptic technique, experienced operator</div><div class=\"answer-line\">Ongoing ascitic leak from</div><div class=\"answer-line\">Use Z-track technique for needle insertion</div><div class=\"answer-line\">puncture site</div><div class=\"answer-line\">Liverpool FEx 2025.2                                                                                                            P Nanaware/J Davidson</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":9,"title":"","stemText":"A 67-year-old female presents with palpitations. She has a history of ischaemic heart disease,\ntype 2 diabetes, peripheral vascular disease and hypertension. Her BMI is 32 kg/m2.\nHer medications include aspirin, bisoprolol and irbesartan. On arrival her vitals are: HR 151bpm, BP 130/85, RR 20, SpO2 99% (room air), T 36.7. Her ECG is shown below:","parts":[{"id":"a","label":"Part A","prompt":"list Three (3) important findings in this ECG. 3marks"},{"id":"b","label":"Part B","prompt":"State your most likely underlying possibility for these ECG Findings. 1mark List Four (4 ) other likely differential for these ECG Findings. 2marks List Four (4) medications likely to precipitate your most likely condition. 4marks List Two (2) medications to treat your most likely condition (include dose and route). 2marks"}],"propPages":["asset:img7466b51c155b68a584"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">A 67 year old female presents with palpitations. She has a history of ischaemic heart disease,</div><div class=\"answer-line\">type 2 diabetes, peripheral vascular disease and hypertension. Her BMI is 32 kg/m2.</div><div class=\"answer-line\">Her medications include aspirin, bisoprolol and irbesartan.</div><div class=\"answer-line\">On arrival her vitals are: HR 151bpm, BP 130/85, RR 20, SpO2 99% (room air), T 36.7.</div><div class=\"answer-line\">Her ECG is shown below:</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">On arrival her vitals are: HR 151bpm, BP 130/85, RR 20, SpO2 99% (room air), T 36.7.</div><div class=\"answer-line\">Her ECG is shown below:</div><div class=\"answer-line\">Liverpool FEx 2025.2                                                                                                            P Nanaware/J Davidson</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":10,"title":"","stemText":"A 47-year-old male is brought into the resuscitation bay of your trauma centre by paramedics with a stab wound to the left side of chest. He is agitated, pale and diaphoretic.\n\nVital signs:\n\nHR 128/min\n\nBP 90/-\n\nRR 28/min\n\nSats 98% on 15L O2 NRBM\nA trauma-call was activated prior to the patient’s arrival, and the team has been assembled.","parts":[{"id":"a","label":"Part A","prompt":"List two (2) indications for Emergency Resuscitative Thoracotomy. 2 marks"},{"id":"b","label":"Part B","prompt":"List two (2) contraindications (excluding the reverse of above points) for Emergency\nResuscitative Thoracotomy. 2 marks\nThe patient becomes unresponsive, and his systolic blood pressure is now 60mmHg."},{"id":"c","label":"Part C","prompt":"Outline your five (5) immediate management priorities as you prepare for thoracotomy. 5 marks"},{"id":"d","label":"Part D","prompt":"List five (5) therapeutic interventions you could undertake once access to the thoracic cavity is\nachieved. 5 marks."},{"id":"e","label":"Part E","prompt":"List two (2) advantages and two disadvantages for utilising either the anterolateral or clamshell\nthoracotomy approach. 4 marks\nAnterolateral Clamshell"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">1. Penetrating chest/epigastric trauma with loss of output for &lt;15mins</div><div class=\"answer-line\">2. Penetrating chest/epigastric trauma with profound hypotension &lt;70mmHg despite blood</div><div class=\"answer-line\">resuscitation &amp; pleural decompression</div><div class=\"answer-line\">3. Blunt trauma with confirmed cardiac tamponade and loss of vital signs in the ED</div><div class=\"answer-line\"><strong>b-List two (2) contraindications (excluding the reverse of above points) for Emergency </strong></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">1. Other unsurvivable injuries</div><div class=\"answer-line\">2. Staff not trained</div><div class=\"answer-line\">3. Penetrating abdominal trauma without cardiac activity</div><div class=\"answer-line\">4. Advanced age/comorbidities</div><div class=\"answer-line\">The patient becomes unresponsive, and his systolic blood pressure is now 60mmHg.</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">1. Obtain intravenous access &amp; <strong>commence blood transfusion</strong> (O-negative blood initially,</div><div class=\"answer-line\">then cross matched)</div><div class=\"answer-line\"><strong>a.</strong><strong> </strong><strong>Activate massive transfusion protocol (MTP)  </strong></div><div class=\"answer-line\">2. Administer TXA (slow IV infusion, 1g over 10 minutes), followed by second infusion (1g in</div><div class=\"answer-line\">100mL over 10 hours).</div><div class=\"answer-line\">3. <strong>Intubate </strong>(RSI) with details - best operator, first pass.</div><div class=\"answer-line\">a. Pre-load first !!</div><div class=\"answer-line\">b. Reduced sedative dosing (No sedation also suitable)</div><div class=\"answer-line\">c. Appropriate NMRB dose (1.5mg/kg Rocuronium minimum)</div><div class=\"answer-line\">d. Prepare for arrest, post institution of positive pressure ventilation</div><div class=\"answer-line\"><strong>4.</strong><strong> </strong><strong>Pleural decompression (or exclusion of tension pneumothorax) </strong></div><div class=\"answer-line\">a. Needle decompression (temporising only)</div><div class=\"answer-line\">b. Open vs tube thoracostomy</div><div class=\"answer-line\">c. Ultrasound for exclusion</div><div class=\"answer-line\">5. Consider pericardiocentesis as temporising measure only</div><div class=\"answer-line\">a. Acknowledge high failure rates (clot!)</div><div class=\"answer-line\">6. Alert Cardiothoracic Surgeon, Anaesthetics, OT…</div><div class=\"answer-line\">Liverpool FEx 2025.2                                                                                                            P Nanaware/J Davidson</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">1. Pericardotomy &amp; release of tamponade</div><div class=\"answer-line\">2. Identification and closure of cardiac laceration</div><div class=\"answer-line\">3. Compression/cross-clamping of descending thoracic aorta</div><div class=\"answer-line\">4. Internal cardiac compressions</div><div class=\"answer-line\">5. Management of pulmonary haemorrhage (hilar twist or tie off vessels)</div><div class=\"answer-line\">6. Control of bronchovenous air embolism</div><div class=\"answer-line\">7. Right atrial catheterisation facilitating IV fluids/blood products administration</div><div class=\"answer-line\"><strong>e-List two (2) advantages and two disadvantages for utilising either the anterolateral or </strong></div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Option</th><th>Advantage</th><th>Disadvantage</th></tr></thead><tbody><tr><td>-direct and quick access to</td><td>- Greater exposure for simultaneous</td><td></td></tr><tr><td>heart/pericardium</td><td>interventions</td><td></td></tr><tr><td><strong>Advantages </strong></td><td>- Easy to close</td><td>- Access both pleural cavities</td></tr><tr><td>- Less morbidity assoc.</td><td>- Better performance/easier for non-</td><td></td></tr><tr><td>surgeons</td><td></td><td></td></tr><tr><td>- Limited access</td><td>- Difficult wound closure</td><td></td></tr><tr><td>- Unfamiliar anatomy</td><td>- Post-op morbidity (pain)</td><td></td></tr><tr><td><strong>Disadvantages </strong></td><td></td><td></td></tr><tr><td>- Limited interventions (esp.</td><td></td><td></td></tr><tr><td>Right chest)</td><td></td><td></td></tr><tr><td>Ref: https://temm.com.au/</td><td></td><td></td></tr><tr><td>Resuscitative Thoracotomy • LITFL • CCC Trauma</td><td></td><td></td></tr><tr><td>2022_DCPM_270723.pdf</td><td></td><td></td></tr><tr><td>------------------------------------------------------------------------------------------------------------------------</td><td></td><td></td></tr><tr><td>Liverpool FEx 2025.2                                                                                                            P Nanaware/J Davidson</td><td></td><td></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":11,"title":"","stemText":"You are the consultant working an evening shift in a regional hospital, when a 19 year old female\nwho is 32/40 weeks pregnant presents with a 2 hour history of severe abdominal pain.","parts":[{"id":"a","label":"Part A","prompt":"List four (4) risk factors for premature Labour. 4 marks"},{"id":"b","label":"Part B","prompt":"List and justify four (4) investigations you would request for this patient. 4 marks"},{"id":"c","label":"Part C","prompt":"State your findings and interpretation for this CTG 2marks"},{"id":"d","label":"Part D","prompt":"List your six (6) immediate management priorities(include drugs/doses/route) 6marks"},{"id":"e","label":"Part E","prompt":"List four (4) contraindications to Tocolysis. 2marks"}],"propPages":["asset:img29c20c60baa6574444"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Maternal –</div><div class=\"answer-line\">Age  &lt;20 years ,&gt; 40 years</div><div class=\"answer-line\">Smoker</div><div class=\"answer-line\">High or low BMI</div><div class=\"answer-line\">No antenatal care</div><div class=\"answer-line\">Lower socio economic</div><div class=\"answer-line\">Indigenous</div><div class=\"answer-line\">Rural/remote</div><div class=\"answer-line\">Pregnancy-</div><div class=\"answer-line\">Multiple pregnancies</div><div class=\"answer-line\">Previous pre term labour</div><div class=\"answer-line\">IVF pregnancy</div><div class=\"answer-line\">Poli/oligo hydramnios</div><div class=\"answer-line\">Anatomical</div><div class=\"answer-line\">Short cervix</div><div class=\"answer-line\">Previous surgical procedure to cervix</div><div class=\"answer-line\">Uterine abnormalities</div><div class=\"answer-line\">Medical</div><div class=\"answer-line\">Infective -UTI, PID</div><div class=\"answer-line\">Pre eclampsia</div><div class=\"answer-line\">Antepartum hemorrhage</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Bedside ultrasound – confirm number of pregnancies</div><div class=\"answer-line\">CTG – establish contraction and foetal viability</div><div class=\"answer-line\">UA – infection , haematuria</div><div class=\"answer-line\">Group and screen – need for anti d and anticipation of blood transfusion</div><div class=\"answer-line\">Actim Partus test – prom</div><div class=\"answer-line\">Cardiotocography (CTG) is performed.</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Liverpool FEx 2025.2                                                                                                            P Nanaware/J Davidson</div><div class=\"answer-line\">Regular contractions</div><div class=\"answer-line\">Beat to beat variability</div><div class=\"answer-line\">Declerations with recovery</div><div class=\"answer-line\">*NORMAL* , Established labour.</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Declare an obstetric emergency- on call obstetrician, contact on call paediatrician</div><div class=\"answer-line\">Move to resus with continuous maternal &amp; foetal monitoring</div><div class=\"answer-line\">Establish IV access</div><div class=\"answer-line\">IV betamethasone 11.4mg x2 doses 24hrs apart</div><div class=\"answer-line\">Nifedipine 20mg stat orally, repeat 30 mins later if no cessation of contractions post 30 minutes</div><div class=\"answer-line\">to a max of 60mg</div><div class=\"answer-line\">IV Ampicillin 2g Q6H OR Amoxicillin 2g Q6H <strong>PLUS</strong> Erythromycin 250mg PO Q6H</div><div class=\"answer-line\">IV Mgso4 4g, 1g/24 hours if labour is established</div><div class=\"answer-line\">Family, patient update</div><div class=\"answer-line\">Documentation</div><div class=\"answer-line\">Liase with local NICU and retrieval service.</div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\">Medical</div><div class=\"answer-line\">Pre-eclampsia (severe)</div><div class=\"answer-line\">Maternal bleeding with hemodynamic instability</div><div class=\"answer-line\">Hypotension /Hemodynamic instability</div><div class=\"answer-line\">Liverpool FEx 2025.2                                                                                                            P Nanaware/J Davidson</div><div class=\"answer-line\">Allergy</div><div class=\"answer-line\">Placental abruption</div><div class=\"answer-line\">Chorioamnionitis</div><div class=\"answer-line\">Foetal compromise</div><div class=\"answer-line\">Foetal Death</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":12,"title":"","stemText":"6 yo girl brought in by parents with neck pain and stiffness She is unable to straighten her neck. (photo attached)","parts":[{"id":"a","label":"Part A","prompt":"State which side is the pathology/affected and why? 2 marks"},{"id":"b","label":"Part B","prompt":"List five (5) causes of acquired torticollis. 5marks"},{"id":"c","label":"Part C","prompt":"List five (5) important features that you will explore in your history and examination. 5 marks\nLiverpool ED FEx 2025.2\nP Nanaware/J Davidson"}],"propPages":["asset:imga528a4b167d66f619c"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Left side torticollis due to ipsilateral sternocleidomastoid spasm</div><div class=\"answer-line\">ipsilateral ear pointing to ipsilateral shoulder and chin pointing to unaffected side</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Muscle spasm (wry neck)</div><div class=\"answer-line\">Trauma: fracture/dislocation, spinal haematoma</div><div class=\"answer-line\">Atlantoaxial rotary subluxation/fixation</div><div class=\"answer-line\">Infection: head and neck, spine, CNS or upper lobe chest</div><div class=\"answer-line\">Inflammation: juvenile idiopathic arthritis</div><div class=\"answer-line\">Neoplasm: CNS (posterior fossa) and bone tumours</div><div class=\"answer-line\">Dystonic syndromes (idiopathic spasmodic torticollis, drug reactions)</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">ipsilateral ear pointing to ipsilateral shoulder and chin pointing to unaffected side</div><div class=\"answer-line\">Muscle spasm (wry neck)</div><div class=\"answer-line\">Trauma: fracture/dislocation, spinal haematoma</div><div class=\"answer-line\">Atlantoaxial rotary subluxation/fixation</div><div class=\"answer-line\">Infection: head and neck, spine, CNS or upper lobe chest</div><div class=\"answer-line\">Inflammation: juvenile idiopathic arthritis</div><div class=\"answer-line\">Neoplasm: CNS (posterior fossa) and bone tumours</div><div class=\"answer-line\">Dystonic syndromes (idiopathic spasmodic torticollis, drug reactions)</div><div class=\"answer-line\">Ocular dysfunction</div><div class=\"answer-line\">Benign paroxysmal torticollis</div><div class=\"answer-line\">Liverpool FEx 2025.2                                                                                                            P Nanaware/J Davidson</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":13,"title":"","stemText":"A 26yo man is brought to your tertiary trauma centre with severe abdominal pain following a football tackle. He believes that he was elbowed to his upper abdomen. He is usually fit and well and is on no regular medications.\nHis vital signs are\n-\n\nHR 110\n-\n\nBP 92/55 (MAP 67)\n-\n\nSPO2 95% on room air\nHe has the following on left upper quadrant view on eFAST He becomes pale and clammy shortly after assessment and his observations are now -\n\nHR 140\n-\n\nBP 72/40 (MAP 51)\n-\n\nSpO2 89% on room air\nYou decide to commence a massive transfusion protocol.\nLiverpool ED FEx 2025.2\nP Nanaware/J Davidson","parts":[{"id":"a","label":"Part A","prompt":"Complete the following table containing variables and their endpoints that should be targeted to achieve haemostatic resuscitation.6 marks Variable Target Following hemostatic resuscitation, he is deemed stable for CT transfer. This is the slice of his axial CT abdomen with contrast"},{"id":"b","label":"Part B","prompt":"List three (3) findings on this CT. 3 marks"},{"id":"c","label":"Part C","prompt":"State your immediate management priorities. 3 marks"}],"propPages":["asset:imgc2d965ba389972a222","asset:imga315549f2713cbf537"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"3\">&gt; 35 °C</td></tr><tr><td><strong>pH </strong></td><td>&gt;7.2</td><td></td></tr><tr><td><strong>Base excess </strong></td><td>&lt;-6</td><td></td></tr><tr><td><strong>Lactate </strong></td><td>&lt;4mmol/L</td><td></td></tr><tr><td><strong>Ionised calcium </strong></td><td>&gt;1.1mmol/L</td><td></td></tr><tr><td><strong>platelets </strong></td><td>&gt;50x109</td><td></td></tr><tr><td><strong>PT/APTT </strong></td><td>&lt;1.5 x normal</td><td></td></tr><tr><td><strong>INR </strong></td><td>&lt;1.5</td><td></td></tr><tr><td><strong>Fibrinogen </strong></td><td>&gt;2g/L</td><td>ITIM:2, LITFL &gt;1</td></tr><tr><td colspan=\"3\">This is the slice of his axial CT abdomen with contrast</td></tr><tr><td colspan=\"3\">Following hemostatic resuscitation, he is deemed stable for CT transfer.</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">- Grade IV splenic laceration</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">-no active blush or contrast extravasation</div><div class=\"answer-line\">Liverpool FEx 2025.2                                                                                                            P Nanaware/J Davidson</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":14,"title":"","stemText":"You are the in-charge consultant of a regional emergency department. A 55yo man has been brought to your ED having collapsed following a witnessed collapse on the golf course. Effective bystander CPR commenced for 10 minutes until ambulance arrival. He has sustained ROSC by the time of ED arrival. He has the following observations -\n\nHR 152, irregularly irregular\n-\n\nBP 158/40mmHg (MAP 79)\n-\n\nTemp: 36.8 deg\n-\n\nGCS: E4V2M4\n-\n\nSpO2 90% via NRBM\n-\n\nRR: 4\n- Pupils: R 3mm, left 7mm","parts":[{"id":"a","label":"Part A","prompt":"Other than lightning strike, list six (6) differentials for this presentation. 6mark On assessment, you noticed rash on patient’s torso and arm. Photo attached\nLiverpool ED FEx 2025.2\nP Nanaware/J Davidson"},{"id":"b","label":"Part B","prompt":"What is the name and significance of this clinical finding. 3 marks"},{"id":"c","label":"Part C","prompt":"List three (3) features specific to lightning strike that are associated with poor neurological\n• utcomes. 3marks"}],"propPages":["asset:img1240f499f2b8faf13f"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">You are the in-charge consultant of a regional emergency department.</td></tr><tr><td colspan=\"2\">A 55yo man has been brought to your ED after a witnessed collapse on the golf course. Effective</td></tr><tr><td colspan=\"2\">bystander CPR was commenced for 10 minutes until ambulance arrival. He has sustained</td></tr><tr><td colspan=\"2\">ROSC by the time of ED arrival.</td></tr><tr><td colspan=\"2\">He has the following observations</td></tr><tr><td>-</td><td>HR 152, irregularly irregular</td></tr><tr><td>-</td><td>BP 158/40mmHg (MAP 79)</td></tr><tr><td>-</td><td>Temp: 36.8 deg</td></tr><tr><td>-</td><td>GCS: E4V2M4</td></tr><tr><td>-</td><td>SpO2 90% via NRBM</td></tr><tr><td>-</td><td>RR: 4</td></tr><tr><td>-</td><td>Pupils: R 3mm, left 7mm</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\"><strong>a-Other than lightning strike, list six (6) differentials for this presentation 6marks </strong></td></tr><tr><td>•</td><td>snake bite /envenomation with paralysis</td></tr><tr><td>•</td><td>cardiac ischaemia/infarction</td></tr><tr><td>•</td><td>Vascular: stroke/ICH</td></tr><tr><td>•</td><td>seizure</td></tr><tr><td>•</td><td>CNS infection meningitis /encephalitis</td></tr><tr><td>•</td><td>Metabolic Hypoglycaemia/hyponatremia/hypercapnia</td></tr><tr><td>•</td><td>Overdose: sedative/GHB/baclofen/alcohol etc</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Liverpool FEx 2025.2                                                                                                            P Nanaware/J Davidson</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":15,"title":"","stemText":"You are working up a patient for suspected haemolytic anaemia.","parts":[{"id":"a","label":"Part A","prompt":"In the table below List Four (4) pertinent history and examinations feature that you will be\nassessing for. 4 marks"},{"id":"b","label":"Part B","prompt":"Other than Full blood count (FBC), List four (4) other investigations with expected findings for\neach. 8marks\nInvestigation Expected finding"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"3\">Liverpool FEx 2025.2                                                                                                            P Nanaware/J Davidson</td></tr><tr><td>History</td><td>Examination</td><td></td></tr><tr><td>1</td><td>Onset acute vs chronic</td><td>pallor</td></tr><tr><td>2</td><td>Recent infection</td><td>jaundice</td></tr><tr><td>3</td><td>Hx medication sulfa drugs eg.</td><td>hepatomegaly</td></tr><tr><td colspan=\"3\">antimalaria</td></tr><tr><td>4</td><td>Autoimmune</td><td>Splenomegaly</td></tr><tr><td colspan=\"3\">disease/haemoglobinopathy</td></tr><tr><td>5</td><td>Symptoms -SOB lethargy</td><td>Lymphadenopathy  ?malignancy</td></tr><tr><td>6</td><td>Recent bloods transfusion,</td><td>Flow murmurs</td></tr><tr><td>7</td><td>G6PD triggers (fava beans)</td><td></td></tr><tr><td colspan=\"3\"><strong>b-Other than Full blood count (FBC) List four (4) other investigations with expected findings </strong></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>o</td><td>Anaemia with elevated reticulocyte count</td></tr><tr><td>o</td><td>Spherocytes, schistocytes, bite cells, nucleated RBCs</td></tr><tr><td>•</td><td><strong>Unconjugated bilirubin</strong>: ↑ (due to breakdown of haem)</td></tr><tr><td>•</td><td><strong>LDH</strong>: ↑ (released from lysed RBCs)</td></tr><tr><td>•</td><td><strong>Haptoglobin</strong>: ↓ (binds free Hb; depleted in haemolysis)</td></tr><tr><td colspan=\"2\"><strong>Determine Underlying Cause  </strong></td></tr><tr><td>•</td><td><strong>Direct Coombs Test (DAT)</strong>:</td></tr><tr><td>o</td><td>Positive in autoimmune haemolysis</td></tr><tr><td>•</td><td><strong>G6PD assay</strong>:</td></tr><tr><td>o</td><td>↓ in G6PD deficiency (may be normal during crisis)</td></tr><tr><td>•</td><td><strong>Hb electrophoresis</strong>:</td></tr><tr><td>o</td><td>For sickle cell disease, thalassaemia</td></tr><tr><td>•</td><td><strong>Cold agglutinins / Donath-Landsteiner test</strong>:</td></tr><tr><td>o</td><td>Suspected cold AIHA / paroxysmal cold haemoglobinuria</td></tr><tr><td>•</td><td><strong>Infectious screen</strong>:</td></tr><tr><td>o</td><td>Malaria blood film, viral serologies (e.g. EBV, HIV)</td></tr><tr><td colspan=\"2\">Liverpool FEx 2025.2                                                                                                            P Nanaware/J Davidson</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":16,"title":"","stemText":"85-year-old woman brought in by ambulance post fall in shower. On exam R knee grossly swollen overlying small wound over medial aspect of knee joint Her past medical history includes morbid obesity Obstructive Sleep Apnoea, End stage renal failure Congestive cardiac failure Diabetes Mellitus. Her Xray is below.","parts":[{"id":"a","label":"Part A","prompt":"List four (4) Important X-ray findings. 4marks List four (4) potential complications of this injury. 4marks Complications This patient is admitted under Orthopaedics team however due to access block remains in your ED overnight waiting for a ward bed. One of the nurses requests you to review her as she is now drowsy and not responding to painful stimulus. List four (4) possible causes for her drowsiness. 4 marks"}],"propPages":["asset:img4a4b539d2a6770686d","asset:img8629367a5a00e1a78f"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">One of the nurses requests you to review her as she is now drowsy and not responding to painful</div><div class=\"answer-line\">stimulus.</div><div class=\"answer-line\">Liverpool FEx 2025.2                                                                                                            P Nanaware/J Davidson</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":17,"title":"","stemText":"A 44 year old female with a history of multiple sclerosis presents with a deliberate overdose of baclofen.","parts":[{"id":"a","label":"Part A","prompt":"List four (4) clinical features of baclofen overdose. 4 marks"},{"id":"b","label":"Part B","prompt":"List six (6) management priorities. 6 marks"},{"id":"c","label":"Part C","prompt":"State two (2) medical indications to clear the patient for discharge following baclofen\n• verdose. 2 marks"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">o Delirium</div><div class=\"answer-line\">o Respiratory depression</div><div class=\"answer-line\">o Seizures</div><div class=\"answer-line\">o Coma, can be profound and prolonged, can mimic brain death and last 24 – 48</div><div class=\"answer-line\">hours</div><div class=\"answer-line\">-</div><div class=\"answer-line\">Cardiovascular</div><div class=\"answer-line\">o Sinus bradycardia</div><div class=\"answer-line\">o Hypotension</div><div class=\"answer-line\">o Frist degree heart block</div><div class=\"answer-line\">o QT prolongation</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Resuscitation and supportive care</div><div class=\"answer-line\">o Respiratory depression and coma necessitate early intubation and</div><div class=\"answer-line\">ventilation</div><div class=\"answer-line\">o Close monitoring of level of consciousness in the first few hours</div><div class=\"answer-line\">o Seizures should be managed with IV diazepam</div><div class=\"answer-line\">o Hypotension usually responds to fluid boluses</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Enhanced elimination</div><div class=\"answer-line\">o Can consider haemodialysis</div><div class=\"answer-line\">-</div><div class=\"answer-line\">Antidotes</div><div class=\"answer-line\">o None available</div><div class=\"answer-line\">Liverpool FEx 2025.2                                                                                                            P Nanaware/J Davidson</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":18,"title":"","stemText":"An 86 yo woman is brought in by ambulance from a nursing home with respiratory distress.\nHer GCS is 8 and she is tachycardic, hypotensive and hypoxic.\nThis is her third presentation in a month with aspiration pneumonia. She is bed bound and fully dependent for activities of daily living. After your assessment and discussion with the family, you have decided that a palliative approach would be in the patient’s best interests.","parts":[{"id":"a","label":"Part A","prompt":"What is the definition of palliative care? 2 marks"},{"id":"b","label":"Part B","prompt":"Other than individual clinical assessment, List two (2) screening tools suggested by ACEM that can be helpful for initiating end of life care. 2 Marks Screening tool After discussion with patient’s family/NOK and palliative care team decision is made to initiate end of life measures for this patient in your ED."},{"id":"c","label":"Part C","prompt":"List four (4) medications (including dose and route) with indication that you would prescribe\nfor this patient. 8 Marks\nMedication Indication Dose Route and Frequency"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">management of a life limiting illness</td></tr><tr><td>•</td><td>focus on quality of life with treatment that is not aimed at a cure</td></tr><tr><td>•</td><td>prevent and treat suffering</td></tr><tr><td>•</td><td>holistic approach addressing physical, emotional, mental, social and spiritual</td></tr><tr><td colspan=\"2\">needs</td></tr><tr><td colspan=\"2\"><span class=\"answer-source-red\">ACEM Definition: </span></td></tr><tr><td colspan=\"2\"><span class=\"answer-source-red\">An approach that improves the quality of life of patients and their families who are facing </span></td></tr><tr><td colspan=\"2\"><span class=\"answer-source-red\">problems associated with life-threatening illness. It seeks to relieve suffering through the </span></td></tr><tr><td colspan=\"2\"><span class=\"answer-source-red\">early identification, correct assessment and treatment of distressing symptoms and other </span></td></tr><tr><td colspan=\"2\"><span class=\"answer-source-red\">problems, whether physical, psychosocial or spiritual.  </span></td></tr><tr><td colspan=\"2\"><strong>b-Other than individual clinical assessment, </strong></td></tr><tr><td colspan=\"2\">List two screening tools suggested by ACEM that can be helpful for initiating end of life</td></tr><tr><td colspan=\"2\">care.  (2 Marks)</td></tr><tr><td colspan=\"2\">- ‘SURPRISE’ question tool</td></tr><tr><td colspan=\"2\">- SPICT (supportive and palliative care indicative tool)</td></tr><tr><td colspan=\"2\">- CFL (clinical frailty scale)</td></tr><tr><td colspan=\"2\">- CriSTAL tool (most validated in ED settings)</td></tr><tr><td colspan=\"2\">Liverpool FEx 2025.2                                                                                                            P Nanaware/J Davidson</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">end of life measures for this patient in your ED.</div><div class=\"answer-line\"><strong>         c- List four medications (including dose and route) with rationale that you would </strong></div><div class=\"answer-line\"><strong>prescribe for this patient to support palliation (8 Marks) </strong></div><div class=\"answer-line\">Medication</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"3\">rational</td></tr><tr><td>Morphine</td><td>2.5-5mg   SC/IV Q2-4H</td><td>Analgesia</td></tr><tr><td>Fentanyl</td><td>25mcg   SC/IV Q2-4H</td><td></td></tr><tr><td>Hydromorphone</td><td>0.5-1mg SC/IV Q2-4H</td><td></td></tr><tr><td>Midazolam</td><td>2.5-5mg  SC/IV</td><td>agitation</td></tr><tr><td>Haloperidol</td><td>0.5-1mg  SC/IV</td><td></td></tr><tr><td>Clonazepam</td><td>0.2-0.5  SC</td><td></td></tr><tr><td>Metoclopramide</td><td>10mg   SC/IV</td><td>Nausea/Vomiting</td></tr><tr><td>Ondansetron</td><td>4-8mg   IV</td><td></td></tr><tr><td>Glycopyrrolate</td><td>100-200mcg SC/IV</td><td>secretions</td></tr><tr><td>Hyoscine hydrobromide</td><td>400mcg SC/IV</td><td></td></tr><tr><td colspan=\"3\">Resources :</td></tr><tr><td colspan=\"3\">https://acem.org.au/getmedia/d55cb8ce-2d26-49d5-823a-</td></tr><tr><td colspan=\"3\">f7f07b5c19cc/Policy_on_End_of_Life_and_Palliative_Care_in_the_ED</td></tr><tr><td colspan=\"3\">https://www.aci.health.nsw.gov.au/__data/assets/pdf_file/0003/346359/Page_66_from_age</td></tr><tr><td colspan=\"3\">d-care-emergency-manual-24032014.pdf</td></tr><tr><td colspan=\"3\">https://www.aci.health.nsw.gov.au/__data/assets/pdf_file/0007/376486/Tools-to-aid-</td></tr><tr><td colspan=\"3\">clinical-identification-of-end-of-life.pdf</td></tr><tr><td colspan=\"3\">https://www.ncbi.nlm.nih.gov/pmc/articles/PMC6267649/</td></tr><tr><td colspan=\"3\">Liverpool FEx 2025.2                                                                                                            P Nanaware/J Davidson</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false}]);
